import React, { useState, useEffect } from 'react';
import axios from 'axios';

const BACKEND_URL = 'http://localhost:5000';

const Dashboard = () => {
  const token = localStorage.getItem('token');

  const [skills, setSkills] = useState([]);
  const [aiSuggestions, setAiSuggestions] = useState({});
  const [loadingSkillId, setLoadingSkillId] = useState(null);

  const fetchSkills = async () => {
    try {
      const res = await axios.get(`${BACKEND_URL}/api/skills`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setSkills(res.data);
    } catch (err) {
      console.error('Failed to fetch skills:', err);
    }
  };

  useEffect(() => {
    fetchSkills();
  }, []);

  const handleDeleteSkill = async (id) => {
    if (!window.confirm('Are you sure you want to delete this skill?')) return;
    try {
      await axios.delete(`${BACKEND_URL}/api/skills/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      fetchSkills();
    } catch (err) {
      alert('Failed to delete skill.');
    }
  };

  const handleEditSkill = (skill) => {
    localStorage.setItem('editSkill', JSON.stringify(skill));
    window.location.href = '/dashboard'; // Will auto-fill via localStorage
  };

  const fetchAiSuggestion = async (skill) => {
    setLoadingSkillId(skill.id);
    setAiSuggestions((prev) => ({ ...prev, [skill.id]: null }));

    try {
      const payload = {
        skillName: skill.name,
        subSkills: skill.subSkills.length
          ? skill.subSkills
          : [{ name: `${skill.name} Basics`, level: Math.round(skill.progress / 10) || 5 }],
      };

      const res = await axios.post(
        `${BACKEND_URL}/api/openai/analyzeSkillLevels`,
        payload,
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      const suggestion = res.data?.suggestion || 'No suggestions available.';
      setAiSuggestions((prev) => ({ ...prev, [skill.id]: suggestion }));
    } catch (error) {
      console.error('Failed to get AI suggestions:', error);
      setAiSuggestions((prev) => ({ ...prev, [skill.id]: 'Failed to get suggestion.' }));
    } finally {
      setLoadingSkillId(null);
    }
  };

  return (
    <div className="container mt-5" style={{ maxWidth: 800 }}>
      <h2>Your Skills</h2>
      <button
        className="btn btn-primary mb-3"
        onClick={() => window.location.href = '/dashboard?mode=add'}
      >
        + Add New Skill
      </button>

      {skills.length === 0 && <p>No skills yet. Add one above.</p>}

      <ul className="list-group">
        {skills.map(skill => (
          <li key={skill.id} className="list-group-item">
            <div className="d-flex justify-content-between align-items-start">
              <div style={{ flex: 1 }}>
                <strong>{skill.name}</strong>
                <div className="progress mt-1" style={{ height: '20px', width: '250px' }}>
                  <div
                    className="progress-bar"
                    role="progressbar"
                    style={{ width: `${skill.progress}%` }}
                    aria-valuenow={skill.progress}
                    aria-valuemin="0"
                    aria-valuemax="100"
                  >
                    {skill.progress}%
                  </div>
                </div>
              </div>
              <div className="d-flex flex-column align-items-end ms-3">
                <button
                  className="btn btn-sm btn-outline-primary mb-1"
                  onClick={() => handleEditSkill(skill)}
                >
                  Edit
                </button>
                <button
                  className="btn btn-sm btn-outline-danger mb-1"
                  onClick={() => handleDeleteSkill(skill.id)}
                >
                  Delete
                </button>
                <button
                  className="btn btn-sm btn-outline-info"
                  disabled={loadingSkillId === skill.id}
                  onClick={() => fetchAiSuggestion(skill)}
                >
                  {loadingSkillId === skill.id ? 'Thinking...' : 'AI Suggestion'}
                </button>
              </div>
            </div>

            {aiSuggestions[skill.id] && (
              <div className="alert alert-info mt-2">
                <strong>AI Suggestion:</strong><br />
                {aiSuggestions[skill.id]}
              </div>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Dashboard;
